 private static <T> T round(Class<T> c,T x){var codec=new ModelCodec<>(c);var y=codec.decode(codec.encode(x));check(x.equals(y));return y;}
 static int run(Path spec)throws Exception{cooldowns();profiles();policy(spec);planning();admin();return n;}
 private static void cooldowns(){var scope=new ScopeRef(ScopeKind.REGION,ID);var inherited=new RegionId(new UUID(0,2));var scopes=new ScopeSet(new WorldId(ID),Set.of(scope,new ScopeRef(ScopeKind.PLAYER,ID)));for(CooldownSelector selector:List.of(new EventCooldownSelector(new DefinitionId("fixture:event")),new FamilyCooldownSelector(Family.HUMOUR),new GlobalSafetyCooldownSelector())){var binding=new CooldownBinding(selector,scopes,Set.of(inherited),true,CooldownReleaseMode.AFTER_TICK_AND_CONDITION,Optional.of(new PlayersPresent(1)));var restored=round(CooldownBinding.class,binding);check(restored.affectedScopes().scopes().contains(new ScopeRef(ScopeKind.PLAYER,ID)));check(restored.inheritedRegions().contains(inherited));check(restored.releasePredicate().isPresent());}
 var unknown=new CooldownRecord(new AggregateHeader(1,ID,new Revision(1),new Sequence(1),new Tick(1)),new ResourceId("fixture:cooldown"),"legacy","safety",new Tick(10),new EventInstanceId(ID),Risk.values()[0],Optional.empty());round(CooldownRecord.class,unknown);check(unknown.binding().isEmpty());var incomplete=new CooldownBinding(new GlobalSafetyCooldownSelector(),scopes,Set.of(),false,CooldownReleaseMode.AFTER_TICK,Optional.empty());check(!round(CooldownBinding.class,incomplete).lineageComplete());reject(()->new CooldownBinding(new GlobalSafetyCooldownSelector(),scopes,Set.of(),true,CooldownReleaseMode.AFTER_TICK_AND_CONDITION,Optional.empty()));}
 private static void profiles(){var region=RegionTrait.values()[0];var low=new DefinitionScoringProfile(1,new DefinitionRef(new DefinitionId("fixture:a"),new Revision(1),HASH),HASH,List.of(new ContextAffinity(new PlayersPresent(1),new UnitValue(.2),new UnitValue(1))),Map.of(region,new UnitValue(.2)),Map.of(GlobalTension.CALM,new UnitValue(.1)),Optional.of(new UnitValue(.2)),Set.of(Family.HUMOUR));var high=new DefinitionScoringProfile(1,new DefinitionRef(new DefinitionId("fixture:b"),new Revision(1),HASH),HASH,List.of(),Map.of(region,new UnitValue(.8)),Map.of(GlobalTension.CALM,new UnitValue(.9)),Optional.of(new UnitValue(.8)),Set.of());check(round(DefinitionScoringProfile.class,low).regionAffinities().get(region).value()!=round(DefinitionScoringProfile.class,high).regionAffinities().get(region).value());check(high.contextAffinities().isEmpty());reject(()->new DefinitionScoringProfile(2,low.definition(),HASH,List.of(),Map.of(),Map.of(),Optional.empty(),Set.of()));}
 private static void policy(Path spec)throws Exception {var envelope=DirectorMessageCodec.decode(Files.readAllBytes(spec.resolve("examples/messages/require.json")));var requirement=(DirectorRequirement)((RequestMessage)envelope.payload()).value();for(var policy:List.of(RequestSchedulingPolicy.legacyWire(),new RequestSchedulingPolicy(new NarrativePriority(9),PreferenceDecay.LINEAR_TO_TTL,RequestPolicySource.AUTHORIZED_ADAPTER))){round(RequestSchedulingPolicy.class,policy);var payload=new DirectorPreference(requirement.requestId(),requirement.selector(),.4,new Tick(500));var e=new DirectorEnvelope(1,envelope.messageId(),envelope.worldId(),envelope.producerId(),envelope.producerKey(),envelope.scope(),envelope.correlationId(),envelope.causationId(),new Sequence(1),Optional.empty(),new Tick(100),PayloadType.DirectorRequest,1,new RequestMessage(payload));var request=MessageContracts.request(e);var state=new DirectorRequestState(new AggregateHeader(1,ID,new Revision(1),new Sequence(1),new Tick(100)),requirement.requestId(),request.producerId(),request.producerKey(),RequestKind.PREFER,requirement.selector(),request.scope(),requirement.targetConstraints(),requirement.fulfillmentMode(),RequestStatus.WAITING_SAFETY,new DurationTicks(0),Optional.of(new Tick(500)),Set.of(),List.of(),policy);var durable=new DurableRequest(e,new RequestView(request,state,new Revision(1)),RequestContracts.idempotenceHash(request));round(DurableRecord.class,durable);check(durable.request().state().schedulingPolicy().equals(policy));check(policy.preferenceMultiplier(new Tick(100),new Tick(500),new Tick(300)).value()==.5);check(policy.preferenceMultiplier(new Tick(100),new Tick(500),new Tick(0)).value()==1);check(policy.preferenceMultiplier(new Tick(100),new Tick(500),new Tick(600)).value()==0);reject(()->policy.preferenceMultiplier(new Tick(100),new Tick(100),new Tick(100)));reject(()->new DurableRequest(e,durable.request(),durable.idempotenceHash(),new Fingerprint("0".repeat(64))));check(DirectorMessageCodec.decode(DirectorMessageCodec.encode(e)).equals(e));}check(!DurableRequest.policyHash(RequestSchedulingPolicy.legacyWire()).equals(DurableRequest.policyHash(new RequestSchedulingPolicy(new NarrativePriority(9),PreferenceDecay.LINEAR_TO_TTL,RequestPolicySource.AUTHORIZED_ADAPTER))));reject(()->new RequestSchedulingPolicy(new NarrativePriority(1),PreferenceDecay.LINEAR_TO_TTL,RequestPolicySource.LEGACY_WIRE_DEFAULT));}
 private static void planning(){var base=ContractTests.context();var old=base.context();var first=old.players().values().iterator().next();var incidental=new PlayerId(new UUID(0,2));var other=new PlayerSnapshot(incidental,first.revision(),first.capturedTick(),first.eligibility(),first.position(),first.regionIds(),first.groupIds(),first.isolatedTicks(),first.observedReactions(),first.clientCapabilities(),first.contextTags());var players=new HashMap<>(old.players());players.put(incidental,other);var rich=new ObservationContext(old.scopes(),players,old.groups(),old.regions(),old.anchors(),old.locations(),old.terrain(),old.capabilities());var context=new SnapshotBatch(base.requestId(),base.scopes(),base.capturedTick(),base.scopeRevisions(),rich,base.missingData(),base.loadedChunks(),base.serverHealth());var footprint=context.context().terrain().getFirst().loadedFootprint();var player=first.playerId();var bindings=new PlanningBindings(new CandidateId(ID),new DefinitionRef(new DefinitionId("fixture:event"),new Revision(1),HASH),new EventInstanceId(ID),new OperationToken(ID),"warn",new RoleAssignments(Map.of("witness",List.of(player))),context.scopes(),footprint,Set.of(incidental),true);var snapshot=new PlanningSnapshot(context,new OwnershipView(Map.of()),new BudgetView(BudgetMath.zero(),BudgetMath.zero(),Map.of()),new BlobBundle(List.of()),Optional.of(bindings));round(PlanningSnapshot.class,snapshot);var step=new EventStep("warn",List.of(),new DurationTicks(0),new PrimitiveId("fixture:sound"),new TargetSound("witness",new ResourceId("fixture:sound"),0,0,0),OnFailure.ABORT_SAFE);var request=new PlanningRequest(step,snapshot);var blob=BlobContent.capture(new ResourceId("fixture:plan"),1,new byte[]{1});var effect=new PreparedEffect(new EffectIntent(bindings.operationToken(),step.primitive(),1,step.args(),footprint,bindings.instanceId()),context,List.of(),new ReadSet(Map.of(),Map.of(),Map.of()),Map.of(),BudgetMath.zero(),List.of(),Set.of(),new EffectBlobs(Set.of(),blob.reference(),blob.reference(),Map.of(),Map.of()));PlanningPort planner=r->new PlannedPrimitive(r.snapshot().bindings().orElseThrow(),effect);check(((PlannedPrimitive)round(PlanningResult.class,planner.plan(request))).effect().snapshot().context().groups().equals(context.context().groups()));PlanningPort needsObservation=r->new DeferredPlanning(List.of(new SampleRequest(context.requestId(),context.scopes(),Set.of(SensorKind.PLAYER_PRESENCE),BudgetMath.zero())),List.of(ReasonCode.values()[0]));check(round(PlanningResult.class,needsObservation.plan(request)) instanceof DeferredPlanning);reject(()->new PlanningRequest(new EventStep("other",List.of(),new DurationTicks(0),step.primitive(),step.args(),step.onFailure()),snapshot));}
 private static void admin(){var session=new SessionId(ID);var stamp=new AdminSnapshotStamp(new WorldId(ID),new Epoch(1),new Revision(8),new Tick(100),new Sequence(40));var current=new AtomicReference<>(new ActorIdentity(session,ActorKind.SERVER,Optional.empty(),Optional.empty(),4,true));var mailbox=new TestRuntimeAdminPort(s->Optional.ofNullable(current.get()),1,stamp);var command=new AdminCommand(session,new RequestId(ID),stamp.snapshotRevision(),AdminOperation.PAUSE,new ControlPayload(RunControl.PAUSED));var key=new RuntimeAdminKey(session,command.requestId());check(round(AdminResult.class,mailbox.submit(command)).status()==AdminStatus.PENDING);check(mailbox.submit(command).status()==AdminStatus.PENDING);check(mailbox.submit(new AdminCommand(session,command.requestId(),stamp.snapshotRevision(),AdminOperation.RESUME,new ControlPayload(RunControl.RUNNING))).status()==AdminStatus.REJECTED);check(mailbox.submit(new AdminCommand(session,new RequestId(new UUID(0,2)),stamp.snapshotRevision(),command.operation(),command.payload())).status()==AdminStatus.DEFERRED);current.set(new ActorIdentity(session,ActorKind.SERVER,Optional.empty(),Optional.empty(),0,true));mailbox.apply(key);check(mailbox.poll(key).status()==AdminStatus.REJECTED&&mailbox.audit().isEmpty());current.set(new ActorIdentity(session,ActorKind.SERVER,Optional.empty(),Optional.empty(),4,true));var success=new TestRuntimeAdminPort(s->Optional.of(current.get()),1,stamp);success.submit(command);success.apply(key);success.apply(key);check(success.audit().size()==1);round(DurableRecord.class,success.audit().getFirst());var empty=new AdminReadResult(AdminStatus.SUCCEEDED,List.of(),Optional.empty(),Optional.empty(),Optional.of(stamp));check(round(AdminReadResult.class,empty).snapshot().orElseThrow().lastDurableSequence().value()==40);}
